            masked_name1 = name1
        else:
            masked_name1 = name1[0] + '*****' + name1[-1]
        return f"{masked_name1}@{name2}.{name3}"
    else:
        digits = re.sub(r'[^0-9]', '', S)
        if len(digits) <= 10:
            return "***-***-" + digits[-4:]
